CREATE FUNCTION public.narrow_repository_monitors(p_provider_id bigint, p_native_id bigint) RETURNS integer LANGUAGE plpgsql AS $$
DECLARE
    narrowed integer;
BEGIN
    WITH monitor_source AS (
        SELECT m.id, m.native_id, p.id AS provider_id
        FROM public.repository_to_monitor AS m
        JOIN public.connection AS c ON c.workspace_id = m.workspace_id
        JOIN public.identity_provider AS p ON p.type = c.kind AND p.server_url = c.config ->> 'serverUrl'
        WHERE c.state IN ('ACTIVE', 'SUSPENDED') AND c.kind IN ('GITHUB', 'GITLAB')
    )
    UPDATE public.repository_to_monitor AS m
    SET proof_generation = m.proof_generation + 1,
        visibility_class = CASE WHEN m.visibility_class = 'WORKSPACE' THEN 'UNPROVEN' ELSE m.visibility_class END,
        proof_state = CASE WHEN m.visibility_class = 'WORKSPACE' THEN 'PENDING' ELSE m.proof_state END,
        proof_reason = CASE WHEN m.visibility_class = 'WORKSPACE' THEN 'AWAITING_READERS' ELSE m.proof_reason END
    FROM monitor_source AS source
    WHERE m.id = source.id
      AND source.provider_id = p_provider_id AND source.native_id = $2;
    GET DIAGNOSTICS narrowed = ROW_COUNT;
    RETURN narrowed;
END
$$;
CREATE OR REPLACE FUNCTION public.narrow_monitors_of_repository() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        PERFORM public.narrow_repository_monitors(OLD.provider_id, OLD.native_id);
    ELSE
        PERFORM public.narrow_repository_monitors(NEW.provider_id, NEW.native_id);
    END IF;
    RETURN NULL;
END
$$;
-- The previous server can still handle GitHub.com visibility events during a rolling upgrade.
CREATE OR REPLACE FUNCTION public.narrow_repository_monitors(p_native_id bigint) RETURNS integer LANGUAGE sql AS $$
    SELECT COALESCE((
        SELECT public.narrow_repository_monitors(p.id, $1)
        FROM public.identity_provider AS p
        WHERE p.type = 'GITHUB' AND p.server_url = 'https://github.com'
    ), 0)
$$;

